import 'package:flutter/material.dart';
import '../../core/mock/mock_data.dart';
import '../home/home_screen.dart';
class DeletionCompleteScreen extends StatelessWidget { final int deletedCount,recoveredBytes,failedCount; const DeletionCompleteScreen({super.key,required this.deletedCount,required this.recoveredBytes,required this.failedCount}); @override Widget build(BuildContext c){final partial=failedCount>0;return Scaffold(body:SafeArea(child:Center(child:Padding(padding:const EdgeInsets.all(28),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(partial?Icons.warning_amber_rounded:Icons.check_circle_rounded,size:86),const SizedBox(height:24),Text(partial?'Deletion completed with some failures':'Files deleted successfully',textAlign:TextAlign.center,style:const TextStyle(fontSize:26,fontWeight:FontWeight.w800)),const SizedBox(height:14),Text('$deletedCount files deleted\n${MockData.formatBytes(recoveredBytes)} recovered${partial?'\n$failedCount files could not be deleted.':''}',textAlign:TextAlign.center,style:const TextStyle(fontSize:16,color:Colors.black54,height:1.5)),const SizedBox(height:34),SizedBox(width:double.infinity,child:FilledButton(onPressed:()=>Navigator.pushAndRemoveUntil(c,MaterialPageRoute(builder:(_)=>const HomeScreen()),(_)=>false),child:const Text('Back to Home')))])))));}}
